class AdditionalServicesDialogController{constructor($mdDialog,$http,jobId,clientId){this._$mdDialog=$mdDialog;this._$http=$http;this.selectedAdditionalServices=[];this._getAdditionalServicesForJob(jobId).then(clientJobs=>{this.selectedAdditionalServices=clientJobs});this.allAdditionalServices=[];this._getAllAdditionalServicesForClient(clientId).then(allClientJobs=>{this.allAdditionalServices=allClientJobs})}async _getAdditionalServicesForJob(jobId){const url="job/GetClientItemsForSingleJob/";return await this._$http.get(url+"?jobId="+jobId)}async _getAllAdditionalServicesForClient(clientId){const url="job/GetAllClientItems/";return await this._$http.get(url+"?clientId="+clientId)}cancel(){this._$mdDialog.cancel()}}